//! Byte-identity check across pqc-sig upgrades.
//!
//! `tests/fixtures/byte_identity_v0.1.4.txt` holds the outputs of every public call that
//! signs with ML-DSA-65, for fixed inputs, generated by pqc-privacy 0.1.4 (pqc-sig 0.4.2).
//! These tests rebuild the same outputs with the current dependencies and require the
//! exact same bytes. A mismatch means a wire-format change, which STABILITY.md treats as
//! breaking.
//!
//! The fixture file was generated once, on the 0.1.4 tree, with:
//!
//! ```text
//! cargo test --test byte_identity -- --ignored regenerate_fixtures
//! ```
//!
//! Do not regenerate it to make a failure go away.

use privacy::interfaces::UniNode;
use privacy::ledger::tuple::{anchor_tuple, build_tuple};
use privacy::mesh::keys::KeyManager;
use privacy::mesh::stake::{commit_stake, generate_stake_keypair};
use privacy::serial::{build_icosuple, build_icosuple_frame};
use privacy::types::{CapabilityKind, PrivacyCapability};

const FIXTURE_PATH: &str = "tests/fixtures/byte_identity_v0.1.4.txt";
const FIXTURE: &str = include_str!("fixtures/byte_identity_v0.1.4.txt");

const SEED_A: [u8; 32] = [0x11; 32];
const SEED_B: [u8; 32] = [
    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e,
    0x0f, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d,
    0x1e, 0x1f,
];

/// Every signed output under test, as `(name, hex)`, computed with the current build.
fn current_outputs() -> Vec<(&'static str, String)> {
    let mut out = Vec::new();

    let (pk, sk) = generate_stake_keypair(&SEED_A).expect("stake keypair");
    out.push(("stake_keypair.public_key", hex::encode(pk)));
    out.push(("stake_keypair.secret_key", hex::encode(sk)));

    let stake = commit_stake(5_000, b"voter-0x307", &SEED_B, 1_700_000_000_000).expect("commit_stake");
    out.push(("commit_stake.commitment", stake.commitment));
    out.push(("commit_stake.signature", stake.signature));
    out.push(("commit_stake.public_key", stake.public_key));

    let frame = build_icosuple_frame(
        b"manifold-tensor".to_vec(),
        b"proof-bundle".to_vec(),
        b"chaos-state".to_vec(),
        &SEED_A,
        true,
    )
    .expect("build_icosuple_frame");
    out.push(("icosuple_frame.signature", hex::encode(&frame.signature)));
    out.push(("icosuple_frame.signing_key_public", hex::encode(&frame.signing_key_public)));

    let ico = build_icosuple(
        b"manifold-tensor".to_vec(),
        b"proof-bundle".to_vec(),
        b"chaos-state".to_vec(),
        &SEED_B,
        false,
    );
    out.push(("icosuple.signature", ico.signature));

    let mut tuple = build_tuple("alice", "holds", b"credential".to_vec(), 1_700_000_000_000, 1.0, &SEED_A)
        .expect("build_tuple");
    out.push(("tuple.anchor", anchor_tuple(&mut tuple)));

    let mut node = UniNode::new("node-0x307");
    node.register_capability(PrivacyCapability {
        kind: CapabilityKind::Zk,
        scheme: "plonk".into(),
        security_level: 128,
        recursion: false,
    });
    let desc = node.advertise(&SEED_B).expect("advertise");
    out.push(("advertise.nonce", hex::encode(desc.nonce.as_bytes())));
    out.push(("advertise.signature", desc.signature));

    let km = KeyManager::new(2, 3);
    let skp = km.generate_keypair(&SEED_A, 1_700_000_000_000).expect("key manager keypair");
    out.push(("signed_keypair.public_key", skp.public_key));
    out.push(("signed_keypair.signature", skp.signature));
    out.push(("signed_keypair.signing_key_public", skp.signing_key_public));

    out
}

fn expected(name: &str) -> &'static str {
    FIXTURE
        .lines()
        .find_map(|line| line.strip_prefix(name)?.strip_prefix('='))
        .unwrap_or_else(|| panic!("fixture has no entry for {name}"))
        .trim()
}

#[test]
fn signed_outputs_match_v0_1_4() {
    let outputs = current_outputs();
    assert_eq!(
        outputs.len(),
        FIXTURE.lines().filter(|l| l.contains('=')).count(),
        "fixture and test cover different outputs"
    );
    for (name, actual) in &outputs {
        assert!(!actual.is_empty(), "{name} is empty");
        assert_eq!(actual, expected(name), "{name} differs from pqc-privacy 0.1.4");
    }
}

#[test]
fn fixture_signatures_still_verify() {
    // The 0.1.4 stake commitment must verify under the current build, independent of
    // whether signing is still deterministic.
    let mut stake = commit_stake(5_000, b"voter-0x307", &SEED_B, 1_700_000_000_000).expect("commit_stake");
    stake.signature = expected("commit_stake.signature").into();
    stake.public_key = expected("commit_stake.public_key").into();
    privacy::mesh::stake::verify_stake(&stake).expect("0.1.4 signature rejected");
}

/// Writes the fixture file from the current build. Run only on the 0.1.4 tree.
#[test]
#[ignore]
fn regenerate_fixtures() {
    let mut text = String::from(
        "# Generated by pqc-privacy 0.1.4 (pqc-sig 0.4.2). See tests/byte_identity.rs.\n",
    );
    for (name, hex) in current_outputs() {
        text.push_str(name);
        text.push('=');
        text.push_str(&hex);
        text.push('\n');
    }
    std::fs::write(FIXTURE_PATH, text).expect("write fixture");
}
